const DIF_PRELOAD_MS=15000;
function difClearPreload(){if(difPreloadTimer){clearTimeout(difPreloadTimer);difPreloadTimer=null}difPreloadToken++}
function difNeedsStartBtn(){const d=jocs.diferencies;return d.missionIndex===0&&d.stars===0}
function difRoundUrls(){const sc=difScene(),urls=[],pend=jocs.diferencies.pendingRound,act=pend?.active||jocs.diferencies.active,dec=pend?.decoys||jocs.diferencies.decoys||[];if(sc?.base)urls.push(strip(sc.base));act.forEach(p=>{if(p?.img)urls.push(strip(p.img))});dec.forEach(p=>{if(p?.img)urls.push(strip(p.img))});return[...new Set(urls.filter(Boolean))]}
function difOnPreloadComplete(){const d=jocs.diferencies;d.assetsReady=true;const ph=d.phase;if(ph==='ready'){if(state.place==='jocsDiferencies')render();return}if(ph==='sceneDone'){if(state.place==='jocsDiferencies')render();return}const pending=d.pendingRound;if(pending){d.active=pending.active;d.decoys=pending.decoys;d.pendingRound=null;d.found=new Set()}if(ph==='found')d.phase='searching';else if(difNeedsStartBtn())d.phase='ready';else d.phase='searching';if(state.place==='jocsDiferencies')render()}
function difPreloadRound(){jocs.diferencies.assetsReady=false;const token=++difPreloadToken;if(difPreloadTimer){clearTimeout(difPreloadTimer);difPreloadTimer=null}const urls=difRoundUrls(),finish=()=>{if(token!==difPreloadToken)return;difPreloadTimer=null;difOnPreloadComplete()};if(!urls.length){finish();return}if(typeof Image==='undefined'){finish();return}let left=urls.length;const step=()=>{if(--left<=0)finish()};difPreloadTimer=setTimeout(finish,DIF_PRELOAD_MS);urls.forEach(src=>{const im=new Image();im.onload=im.onerror=step;im.src=src})}
const OMBRES_NOPE_MS=400;
const OMBRES_WRONG_MSG_MS=1500;
function difClearAuto(){if(difAutoTimer){clearTimeout(difAutoTimer);difAutoTimer=null}difClearPreload()}
function difRoundsGoalEffective(){const ctx=jocs.diferencies?.context;return ctx?.mode==='missio'&&ctx.roundsGoal!=null?Math.max(1,Math.min(4,Math.floor(ctx.roundsGoal))):difRoundsGoal()}
function difSessionIdNew(){return typeof activitatsSessionId==='function'?activitatsSessionId():`s${Date.now().toString(36)}${Math.random().toString(36).slice(2,10)}`}
function difActivitatsRuntimeOn(){return typeof activitatsReg!=='undefined'&&activitatsReg.ready&&!activitatsReg.failed}
function difContextLliure(){return {mode:'lliure',forcedSceneId:null,roundsGoal:null,returnPlace:null}}
function difPrepareFreeSession(){jocs.diferencies.context=difContextLliure()}
function difDiferenciesStartMission(opts){const o=opts||{};jocs.diferencies.context={mode:'missio',missioId:o.missioId||null,forcedSceneId:o.sceneId||null,roundsGoal:o.roundsGoal??1,returnPlace:o.returnPlace||null};jocs.diferencies.sessionId=o.sessionId||jocs.diferencies.sessionId||difSessionIdNew();jocs.diferencies.sessionVictoryRecorded=false}
function difRegisterSessionVictory(){if(jocs.diferencies.sessionVictoryRecorded)return;if(jocs.diferencies.context?.mode==='missio')return;jocs.diferencies.sessionVictoryRecorded=true;const sid=jocs.diferencies.sessionId;if(!sid)return;if(typeof activitatCompleta==='function')activitatCompleta('diferencies',{sessionId:sid,sceneId:jocs.diferencies.sceneId,ambit:'sessio',mode:'lliure'});else if(typeof remember==='function')remember('jocs-diferencies')}
function difRegisterMissionVictory(){if(jocs.diferencies.sessionVictoryRecorded)return;if(jocs.diferencies.context?.mode!=='missio')return;jocs.diferencies.sessionVictoryRecorded=true;const sid=jocs.diferencies.sessionId;if(!sid)return;const ctx=jocs.diferencies.context||{};if(typeof activitatCompleta==='function')activitatCompleta('diferencies',{sessionId:sid,sceneId:jocs.diferencies.sceneId,ambit:'ronda',mode:'missio',missioId:ctx.missioId||null})}
function difScheduleAdvance(){difClearAuto();const goal=difRoundsGoalEffective();const ms=jocs.diferencies.stars>=goal?1500:1100;difAutoTimer=setTimeout(()=>{difAutoTimer=null;if(state.place!=='jocsDiferencies'||jocs.diferencies.phase!=='found')return;if(jocs.diferencies.stars>=goal)jocs.diferencies.phase='completed';else difAdvanceRound();render()},ms)}
function ombresNopeBump(pic){if(!pic)return;pic.style.animation='none';void pic.offsetWidth;pic.style.removeProperty('animation')}
function ombresClearNopeFig(el){if(!el)return;const id=el.getAttribute('data-ombres-id');if(id&&jocs.ombres.nopeShake)jocs.ombres.nopeShake.delete(id);if(el._ombresNopeT){clearTimeout(el._ombresNopeT);el._ombresNopeT=null}ombresNopeBump(el.querySelector('.ombres-fig-pic'))}
function ombresClearAllNope(){jocs.ombres.nopeShake=new Set();const wall=app.querySelector('[data-ombres-wall]');if(!wall)return;wall.querySelectorAll('[data-ombres-id]').forEach(ombresClearNopeFig)}
function ombresClearWrongMsg(){if(jocs.ombres?.wrongMsgTimer){clearTimeout(jocs.ombres.wrongMsgTimer);jocs.ombres.wrongMsgTimer=null}if(jocs.ombres)jocs.ombres.wrongMsgId=null}
function ombresClearAuto(){if(ombresAutoTimer){clearTimeout(ombresAutoTimer);ombresAutoTimer=null}ombresClearAllNope();ombresClearWrongMsg()}
function ombresCfg(){return jocs.ombres.data||{missions:{},secrets:[]}}
function ombresMissions(){return ombresCfg().missions||{}}
function ombresAllSecrets(){return ombresCfg().secrets||[]}
function ombresSecrets(){if(jocs.ombres.activeSecrets.length)return jocs.ombres.activeSecrets;const ph=jocs.ombres?.phase;if(ph==='pickLevel'||ph==='briefing')return[];return ombresAllSecrets()}
function ombresObjective(id){return strip((ombresMissions().objectives||{})[id]||'BUSCA!')}
function ombresFoundLabel(id){return strip((ombresMissions().foundLabels||{})[id]||ombresObjective(id).replace(/^BUSCA/,'HAS TROBAT'))}
function ombresTargetText(id){return jocs.ombres.phase==='found'?ombresFoundLabel(id):ombresObjective(id)}
function ombresPlayingLevel(){return Math.max(0,Math.min(3,Number.isInteger(jocs.ombres.playingLevel)?jocs.ombres.playingLevel:0))}
function ombresMissionSize(){const lv=OMBRES_LEVEL_SIZES[ombresPlayingLevel()]||OMBRES_LEVEL_SIZES[0];return lv[Math.min(2,Math.max(0,jocs.ombres.missionIndex))]||lv[0]}
function ombresSaveSession(){if(typeof sessionStorage==='undefined'||!f2.ombresSession)return;try{sessionStorage.setItem(OMBRES_SS_KEY,JSON.stringify(f2.ombresSession))}catch(_){}}
function ombresLoadSession(){if(typeof sessionStorage==='undefined')return null;try{const raw=sessionStorage.getItem(OMBRES_SS_KEY);if(!raw)return null;const s=JSON.parse(raw);return s&&Number.isInteger(s.levelUnlocked)?s:null}catch(_){return null}}
function ombresEnsureSession(){const s=ombresLoadSession();f2.ombresSession=s?{levelUnlocked:Math.min(3,Math.max(0,s.levelUnlocked)),playingLevel:Math.min(3,Math.max(0,s.playingLevel||0)),levelsCompleted:Array.isArray(s.levelsCompleted)?s.levelsCompleted:[],adventureTargets:Array.isArray(s.adventureTargets)?s.adventureTargets:[]}: {levelUnlocked:0,playingLevel:0,levelsCompleted:[],adventureTargets:[]}}
function ombresPositionsOk(list){for(let i=0;i<list.length;i++)for(let j=i+1;j<list.length;j++){const dx=list[i].x-list[j].x,dy=list[i].y-list[j].y;if(Math.hypot(dx,dy)<OMBRES_MIN_POS_DIST)return false}return true}
function ombresGreedyPositions(secrets,pos){for(let a=0;a<80;a++){const pool=jocsShuffle(pos),placed=[];let fail=false;for(const s of secrets){let hit=null;for(const p of pool){const trial={...s,x:p.x,y:p.y};if(placed.every(q=>Math.hypot(trial.x-q.x,trial.y-q.y)>=OMBRES_MIN_POS_DIST)){hit=trial;break}}if(!hit){fail=true;break}placed.push(hit)}if(!fail&&ombresPositionsOk(placed))return placed}return null}
function ombresShufflePositions(secrets){const pos=ombresAllSecrets().map(s=>({x:s.x,y:s.y}));for(let t=0;t<100;t++){const sh=jocsShuffle(pos),placed=secrets.map((s,i)=>({...s,x:sh[i].x,y:sh[i].y}));if(ombresPositionsOk(placed))return placed}const g=ombresGreedyPositions(secrets,pos);if(g)return g;return secrets.map((s,i)=>({...s,x:pos[i%pos.length].x,y:pos[i%pos.length].y}))}
function ombresPickTarget(exclude){ombresEnsureSession();const all=ombresAllSecrets().map(s=>s.id),adv=f2.ombresSession.adventureTargets||[];let pool=all.filter(id=>!jocs.ombres.usedTargets.includes(id)&&id!==exclude);if(!pool.length)pool=all.filter(id=>id!==exclude);const fresh=pool.filter(id=>!adv.includes(id));if(fresh.length)pool=fresh;if(jocs.ombres.missionIndex===0&&!jocs.ombres.usedTargets.length&&ombresLastTargetId&&pool.length>1)pool=pool.filter(id=>id!==ombresLastTargetId);return pool[Math.floor(Math.random()*pool.length)]}
function ombresTeachTap(){return ombresPlayingLevel()===0&&jocs.ombres.missionIndex===0&&jocs.ombres.stars===0}
function ombresLightClear(lx,ly,list){for(const s of list){if(Math.hypot(s.x-lx,s.y-ly)<=s.r*1.35+.4)return false}return true}
function ombresResetLight(){const list=ombresSecrets();if(!list.length){jocs.ombres.lx=12;jocs.ombres.ly=18;return}const cand=[[12,18],[88,18],[12,82],[88,82],[50,12],[50,88],[18,50],[82,50],[6,28],[94,72]];for(const [lx,ly] of cand){if(ombresLightClear(lx,ly,list)){jocs.ombres.lx=lx;jocs.ombres.ly=ly;jocs.ombres.inLightWrong=new Set();return}}let best=[12,18],bestD=-1;cand.forEach(([lx,ly])=>{const minD=Math.min(...list.map(s=>Math.hypot(s.x-lx,s.y-ly)-s.r*1.35));if(minD>bestD){bestD=minD;best=[lx,ly]}});jocs.ombres.lx=best[0];jocs.ombres.ly=best[1];jocs.ombres.inLightWrong=new Set()}
function ombresPrepMission(phase){const all=ombresAllSecrets(),n=Math.min(ombresMissionSize(),all.length),targetId=jocs.ombres.nextTargetId||(jocs.ombres.targetId||ombresPickTarget());jocs.ombres.targetId=targetId;jocs.ombres.nextTargetId=null;const others=jocsShuffle(all.filter(s=>s.id!==targetId)).slice(0,n-1),chosen=[all.find(s=>s.id===targetId),...others];jocs.ombres.activeSecrets=ombresShufflePositions(chosen);jocs.ombres.found=new Set();jocs.ombres.inLightWrong=new Set();jocs.ombres.nopeShake=new Set();jocs.ombres.wrongMsgId=null;ombresClearWrongMsg();jocs.ombres.phase=phase==='searching'?'searching':'briefing';ombresResetLight()}
function ombresHasProgress(){ombresEnsureSession();const s=f2.ombresSession||{};return(s.levelUnlocked||0)>0||(s.levelsCompleted||[]).length>0}
function ombresSessionIdNew(){return typeof activitatsSessionId==='function'?activitatsSessionId():`s${Date.now().toString(36)}${Math.random().toString(36).slice(2,10)}`}
function ombresApplyLevelUnlock(lvl){ombresEnsureSession();if(!f2.ombresSession.levelsCompleted.includes(lvl))f2.ombresSession.levelsCompleted.push(lvl);f2.ombresSession.levelUnlocked=Math.max(f2.ombresSession.levelUnlocked,Math.min(3,lvl+1));ombresSaveSession()}
function ombresRegisterLevelVictory(){if(jocs.ombres.levelVictoryRecorded)return;jocs.ombres.levelVictoryRecorded=true;const lvl=ombresPlayingLevel(),sid=jocs.ombres.sessionId;if(!sid)return;ombresApplyLevelUnlock(lvl);const gm=f2.granMissio,detail={sessionId:sid,nivell:lvl};if(gm?.activitatId==='ombres'){detail.mode='missio';detail.missioId=gm.missioId}if(typeof activitatCompleta==='function')activitatCompleta('ombres',detail);else if(lvl===3&&typeof remember==='function')remember('jocs-ombres')}
function ombresActivitatsRuntimeOn(){return typeof activitatsReg!=='undefined'&&activitatsReg.ready&&!activitatsReg.failed}
function ombresNovaAventura(){ombresClearAuto();ombresEnsureSession();f2.ombresSession={levelUnlocked:0,playingLevel:0,levelsCompleted:[],adventureTargets:[]};ombresSaveSession();ombresLastTargetId=null;ombresStartLevel(0)}
function ombresStartLevel(idx,sessionIdOpt){ombresClearAuto();ombresEnsureSession();const lvl=Math.max(0,Math.min(3,idx));jocs.ombres.playingLevel=lvl;f2.ombresSession.playingLevel=lvl;jocs.ombres.missionIndex=0;jocs.ombres.stars=0;jocs.ombres.usedTargets=[];jocs.ombres.activeSecrets=[];jocs.ombres.found=new Set();jocs.ombres.inLightWrong=new Set();jocs.ombres.nopeShake=new Set();jocs.ombres.wrongMsgId=null;ombresClearWrongMsg();jocs.ombres.starPop=false;jocs.ombres.sessionId=sessionIdOpt||jocs.ombres.sessionId||ombresSessionIdNew();jocs.ombres.levelVictoryRecorded=false;jocs.ombres.targetId=jocs.ombres.nextTargetId||ombresPickTarget();jocs.ombres.nextTargetId=null;jocs.ombres.phase='briefing';jocs.ombres.lx=42;jocs.ombres.ly=52;ombresSaveSession()}
function ombresStarsHtml(){const n=jocs.ombres.stars,pop=jocs.ombres.starPop;return [0,1,2].map(i=>`<span class="ombres-star ${i<n?'ombres-star--on':''} ${i===n-1&&pop?'ombres-star--pop':''}" aria-hidden="true"><svg class="ombres-star-svg" viewBox="0 0 64 64"><path d="M32 5 39 25 61 27 45 42 51 63 32 52 13 63 19 42 3 27 25 25Z"/></svg></span>`).join('')}
