function ombresHeadHtml(){const m=ombresMissions();const ph=jocs.ombres.phase;if(ph==='completed'||ph==='levelDone'||ph==='pickLevel'||ph==='briefing')return'';const showGoal=ph==='found'||ph==='searching';const hint=strip(m.hint||'');return `<div class="ombres-head"${hint?` aria-label="${hint}"`:''}><div class="ombres-head-main">${showGoal?ombresTargetRow():''}<div class="ombres-stars" aria-label="${strip(m.starsLabel||'Estrelles')}">${ombresStarsHtml()}</div></div></div>`}
