function ombresPrepObjectiveHtml(s){if(!s)return'';return `<div class="ombres-objective ombres-prep-objective"><img class="ombres-objective-thumb" src="${strip(s.img)}" alt=""><p class="ombres-objective-text">${ombresObjective(s.id)}</p></div>`}
