function ombresGuideHtml(hint){const g=ombresGuideSecret(),msg=strip(hint||ombresMissions().hint||'MOU LA LLUM I TROBA L\'OMBRA!');if(!g)return msg?`<p class="dif-ready-hint">${msg}</p>`:'';return `<div class="ombres-prep-guide"><div class="ombres-prep-guide-row"><figure class="ombres-prep-friend f2-pairs-friend f2-pairs-friend--mid"><img src="${strip(g.color||g.img)}" alt="" decoding="async" draggable="false"><figcaption>${strip(g.name||'EN ROSSET')}</figcaption></figure>${msg?`<p class="ombres-prep-bubble" role="note">${msg}</p>`:''}</div></div>`}
