function ombresFullPrepEntryGuideHtml(){const g=ombresGuideSecret(),m=ombresMissions(),msg=strip(m.hint||'MOU LA LLUM I TROBA L\'OMBRA!');if(!g||!msg)return'';return `<div class="ombres-prep-guide ombres-prep-guide--entry"><div class="ombres-prep-guide-row"><figure class="ombres-prep-friend f2-pairs-friend f2-pairs-friend--mid" aria-hidden="true"><img src="${strip(g.color||g.img)}" alt="" decoding="async" draggable="false"></figure><p class="ombres-prep-bubble" role="note">${msg}</p></div></div>`}
