function ombresPickLevelHtml(){ombresEnsureSession();const max=f2.ombresSession?.levelUnlocked??0,fresh=ombresFullPrepEntry();let btns='';for(let i=0;i<=max;i++)btns+=ombresLevelBtn(fresh&&i===0&&!max?'COMENÇAR NIVELL 1':`NIVELL ${i+1}`,`ombres-play-level-${i}`,fresh&&i===0&&!max?'primary':'secondary');const nova=ombresHasProgress()?`<div class="ombres-level-pick-nova">${ombresLevelBtn('NOVA AVENTURA','ombres-nova-aventura','secondary')}</div>`:'';if(!fresh)return `<div class="ombres-pop ombres-pop--levels" role="dialog" aria-modal="true"><div class="ombres-pop-card ombres-pop-card--levels"><div class="ombres-level-pick">${btns}</div>${nova}</div></div>`;const teach=ombresTeachSecret(),levelBtns=`<div class="ombres-level-btns-primary"><div class="ombres-level-pick">${btns}</div>${nova}</div>`;return ombresFullPrepEntryHtml(teach,levelBtns)}
