function resetOmbres(){ombresClearAuto();const {data,load}=jocs.ombres;if(jocs.ombres.targetId)ombresLastTargetId=jocs.ombres.targetId;ombresEnsureSession();jocs.ombres={data,load,lx:42,ly:52,found:new Set(),stars:0,missionIndex:0,phase:'pickLevel',targetId:null,usedTargets:[],activeSecrets:[],inLightWrong:new Set(),nopeShake:new Set(),wrongMsgId:null,wrongMsgTimer:null,playingLevel:0,starPop:false,sessionId:null,levelVictoryRecorded:false}}
function difCfg(){return jocs.diferencies.data||{}}
function difScenes(){const c=difCfg();if(Array.isArray(c.scenes)&&c.scenes.length)return c.scenes;if(c.scene)return [{id:'biblioteca',label:'La biblioteca',...c.scene}];return[]}
function difScenePlayable(s){const n=s?.perRound??difCfg().perRound??5;return Array.isArray(s?.diffs)&&s.diffs.length>=n}
function difPickSceneId(){const scenes=difScenes().filter(difScenePlayable);if(!scenes.length)return null;const forced=jocs.diferencies.context?.mode==='missio'&&jocs.diferencies.context.forcedSceneId;if(forced&&scenes.some(s=>s.id===forced))return forced;if(scenes.length===1)return scenes[0].id;let pool=scenes.map(s=>s.id);const fresh=pool.filter(id=>!difRecentScenes.includes(id));if(fresh.length)pool=fresh;const id=pool[Math.floor(Math.random()*pool.length)];difLastSceneId=id;difRecentScenes=[id,...difRecentScenes.filter(x=>x!==id)].slice(0,Math.min(difRoundsGoal(),scenes.length-1));return id}
function difScene(){const scenes=difScenes(),id=jocs.diferencies.sceneId||scenes[0]?.id;return scenes.find(s=>s.id===id)||scenes[0]||null}
function difAll(){return difScene()?.diffs||[]}
function difSpots(d){return d?.spots?.length?d.spots:(d?.x!=null?[{x:d.x,y:d.y,w:d.w,r:d.r||8}]:[])}
function difSampleZone(z){const loX=Math.min(z.x0,z.x1),hiX=Math.max(z.x0,z.x1),loY=Math.min(z.y0,z.y1),hiY=Math.max(z.y0,z.y1);return {x:loX+Math.random()*(hiX-loX),y:loY+Math.random()*(hiY-loY),w:z.w,r:z.r||8}}
function difBuildPlacement(d){if(d.zones?.length){const z=d.zones[Math.floor(Math.random()*d.zones.length)],s=difSampleZone(z);return {id:d.id,img:d.img,message:d.message,...s}}const spots=difSpots(d),s=spots[Math.floor(Math.random()*spots.length)];return {id:d.id,img:d.img,message:d.message,x:s.x,y:s.y,w:s.w,r:s.r||8}}
function difSpotDist(){const sc=difScene();return sc?.minSpotDist||difCfg().minSpotDist||DIF_MIN_SPOT_DIST}
function difPerRound(){const sc=difScene();return sc?.perRound||difCfg().perRound||5}
function difRoundsGoal(){const c=difCfg();return Math.min(4,Math.max(1,Math.floor(c.roundsPerSession)||4))}
function difSessionRoundIndex(){const d=jocs.diferencies||{};return Math.max(0,Math.min(3,Math.max(Number.isFinite(d.missionIndex)?d.missionIndex:0,Number.isFinite(d.stars)?d.stars:0)))}
function difPerRoundDecoys(){const sc=difScene(),v=sc?.perRoundDecoys??difCfg().perRoundDecoys??1,floor=Math.max(0,Math.min(4,Math.floor(v))),fromSession=Math.min(4,difSessionRoundIndex()+1);return Math.max(floor,fromSession)}
function difPlacementsOk(list){const minD=difSpotDist();for(let i=0;i<list.length;i++)for(let j=i+1;j<list.length;j++){const dx=list[i].x-list[j].x,dy=list[i].y-list[j].y;if(Math.hypot(dx,dy)<minD)return false}return true}
function difSig(list){const sc=jocs.diferencies.sceneId||'';return sc+'|'+list.map(p=>`${p.id}@${Math.round(p.x)}@${Math.round(p.y)}`).sort().join('|')}
function difPickRound(){const all=difAll(),n=Math.min(difPerRound(),all.length),dcN=Math.min(difPerRoundDecoys(),Math.max(0,all.length-n));for(let t=0;t<300;t++){const sh=jocsShuffle(all),picked=sh.slice(0,n),active=picked.map(difBuildPlacement);if(!difPlacementsOk(active))continue;let decoys=[];if(dcN>0){decoys=sh.slice(n,n+dcN).map(difBuildPlacement);if(!difPlacementsOk(active.concat(decoys)))continue}const sig=difSig(active.concat(decoys));if(sig!==difLastSig||t>200){difLastSig=sig;return {active,decoys}}}return difGreedyRound(all,n,dcN)}
function difGreedyRound(all,n,dcN){let best=[];for(let t=0;t<200&&best.length<n+dcN;t++){const placed=[];for(const d of jocsShuffle(all)){if(placed.length>=n+dcN)break;for(let k=0;k<12;k++){const p=difBuildPlacement(d);if(difPlacementsOk(placed.concat(p))){placed.push(p);break}}}if(placed.length>best.length)best=placed}return {active:best.slice(0,n),decoys:best.slice(n,n+dcN)}}
